type Train = { id: string; name: string; type: string; currentStation: string; nextStation: string; speed: number; status: string; eta: string; priority: string };
type Asset = { id: string; type: string; section: string; health: number; risk: string; temperature: number; vibration: number; usage: number; lastMaintenance: string; predictedMaintenance: string; failureProbability: number };
type MaintenanceRequest = { id: string; department: string; assetId: string; section: string; date: string; startTime: string; duration: number; priority: string; status: string; risk: string; recommendation: string };
type Conflict = { id: string; section: string; trainId: string; requestId: string; severity: string; resolution: string };
type BlockOption = { startTime: string; endTime: string; conflicts: number; disruptionScore: number; confidence: number; riskReduction: number; recommended: boolean };
type Recommendation = { id: string; priority: string; reason: string; impact: string; confidence: number; status: string };
type Notice = { id: number; tone: 'success' | 'warn' | 'info'; text: string };

